CREATE TABLE "owner_earning_settlements" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "owner_earning_settlements_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"booking_id" bigint NOT NULL,
	"owner_id" bigint NOT NULL,
	"amount" numeric(14, 2) NOT NULL,
	"status" varchar NOT NULL,
	"mode" varchar NOT NULL,
	"ledger_entry_id" bigint,
	"decided_by" bigint,
	"decided_at" timestamp,
	"note" varchar(500),
	"created_at" timestamp DEFAULT now() NOT NULL,
	"updated_at" timestamp DEFAULT now() NOT NULL,
	CONSTRAINT "chk_owner_earning_amount" CHECK ("owner_earning_settlements"."amount" > 0),
	CONSTRAINT "chk_owner_earning_status" CHECK ("owner_earning_settlements"."status" IN ('PENDING', 'CREDITED', 'REJECTED')),
	CONSTRAINT "chk_owner_earning_mode" CHECK ("owner_earning_settlements"."mode" IN ('AUTO', 'MANUAL'))
);
