INSERT INTO "owner_earning_settlements" ("booking_id", "owner_id", "amount", "status", "mode", "ledger_entry_id", "decided_at", "created_at", "updated_at")
SELECT l.reference_id, l.user_id, l.amount, 'CREDITED', 'AUTO', l.id, l.created_at, l.created_at, l.created_at
FROM "wallet_ledger_entries" l
WHERE l.entry_type = 'OWNER_EARNING'
  AND l.reference_type = 'BOOKING'
  AND l.reference_id IS NOT NULL
ON CONFLICT ("booking_id") DO NOTHING;
